#[test]
fn rename_of_const_rewrites_const_block_not_the_shadowing_local() {
    // Locals do not enter a `const { }` (SPEC / rustc E0435). The `k` in the
    // const block is the file-level const, even when a local `k` shadows it
    // in the function body.
    let store = MemStore::new();
    let langs = rust_langs();
    let path = RelPath::new("src/lib.rs").unwrap();
    let mut files = BTreeMap::new();
    files.insert(
        path.clone(),
        b"const k: u8 = 1;\nfn f() { let k = 2u8; const { let _ = k; } let _ = k; }\n".to_vec(),
    );
    let snap = snapshot_files(&store, &langs, &files, None, ChangeId::new()).unwrap();
    let c = named_in_file(&snap, "k", &path);
    let next = rename(&store, &snap, c, "key").unwrap();
    let rendered = render(&next, &store, &langs, false).unwrap();
    let text = String::from_utf8(rendered.files[&path].clone()).unwrap();
    assert!(text.contains("const key: u8 = 1"), "{text}");
    assert!(
        text.contains("const { let _ = key; }"),
        "const block must see the file const: {text}"
    );
    assert!(text.contains("let k = 2u8"), "local must stay: {text}");
    assert!(
        text.contains("let _ = k;"),
        "use of the local must stay: {text}"
    );
}

#[test]
fn rename_of_fn_does_not_rewrite_struct_pattern_field() {
    let store = MemStore::new();
    let langs = rust_langs();
    let path = RelPath::new("src/lib.rs").unwrap();
    let mut files = BTreeMap::new();
    files.insert(
        path.clone(),
        b"fn item() {}\nstruct S { item: u8 }\nfn f(s: S) { let S { item: x } = s; item(); }\n"
            .to_vec(),
    );
    let snap = snapshot_files(&store, &langs, &files, None, ChangeId::new()).unwrap();
    let f = named_in_file(&snap, "item", &path);
    let next = rename(&store, &snap, f, "item2").unwrap();
    let rendered = render(&next, &store, &langs, false).unwrap();
    let text = String::from_utf8(rendered.files[&path].clone()).unwrap();
    assert!(text.contains("fn item2()"), "{text}");
    assert!(text.contains("item2()"), "{text}");
    assert!(
        text.contains("let S { item: x }"),
        "pattern field name must stay: {text}"
    );
}

crates/svc-core/tests/visibility.rs.Text:
//! Visibility variants the role table already emits must change what
//! `resolve_locals` reports. Audit A2: only AfterStmt was interpreted.

use std::collections::BTreeMap;

use svc_core::content::{IdentRef, Namespace};
use svc_core::engine::{env_from_snapshot, parse, resolve, rust_langs, snapshot_files};
use svc_core::ids::{ChangeId, RelPath, Slot};
use svc_core::lang::Env;
use svc_core::store::MemStore;
use svc_core::{JsLang, Kind, RustLang};

fn rust_item_refs(src: &str) -> Vec<(String, IdentRef)> {
    let lang = RustLang;
    let tree = parse(src.as_bytes(), &lang).unwrap();
    let item = tree.root_node().named_child(0).expect("one item");
    let res = resolve(item, src.as_bytes(), &lang, &Env::default()).unwrap();
    res.refs
        .iter()
        .map(|(r, ident)| {
            (
                String::from_utf8_lossy(&src.as_bytes()[r.start as usize..r.end as usize])
                    .into_owned(),
                ident.clone(),
            )
        })
        .collect()
}

fn js_item_refs(src: &str) -> Vec<(String, IdentRef)> {
    let lang = JsLang;
    let tree = parse(src.as_bytes(), &lang).unwrap();
    let item = tree.root_node().named_child(0).expect("one item");
    let res = resolve(item, src.as_bytes(), &lang, &Env::default()).unwrap();
    res.refs
        .iter()
        .map(|(r, ident)| {
            (
                String::from_utf8_lossy(&src.as_bytes()[r.start as usize..r.end as usize])
                    .into_owned(),
                ident.clone(),
            )
        })
        .collect()
}

fn locals_named(refs: &[(String, IdentRef)], name: &str) -> Vec<Slot> {
    refs.iter()
        .filter_map(|(n, ident)| match ident {
            IdentRef::Local(slot, Namespace::Value) if n == name => Some(*slot),
            _ => None,
        })
        .collect()
}

fn frees_named(refs: &[(String, IdentRef)], name: &str) -> usize {
    refs.iter()
        .filter(|(n, ident)| n == name && matches!(ident, IdentRef::Free(_)))
        .count()
}

#[test]
