        .count();
    let labels: Vec<_> = refs.iter().filter(|(n, _)| n == "loop").cloned().collect();
    assert!(
        !labels
            .iter()
            .any(|(_, ident)| matches!(ident, IdentRef::Local(_, Namespace::Value))),
        "break loop must not resolve as the var: {labels:?}"
